# 049 - registrazione: il formato vero del driver

import sys


def traccia(testo):
    riga = '[049] %s' % testo
    try:
        print(riga)
    except Exception:
        pass
    try:
        import datetime
        import os
        d = os.path.join(os.environ.get('LOCALAPPDATA') or
                         os.path.expanduser('~'), 'KaraDom')
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, 'patch049.log'), 'a', encoding='utf-8') as f:
            f.write('%s  %s%s' % (
                datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                riga, chr(10)))
    except Exception:
        pass


CODICE = '# -*- coding: utf-8 -*-\n"""\nRegistrazione MULTITRACCIA via BASSASIO.\n\nRiusa lo STESSO device ASIO dell\'XR18 già aperto dalla voce guida\n(cuffia_guida) — un solo host ASIO, niente conflitti mono-client —\ne cattura i canali di INGRESSO (USB sends del mixer) scrivendo\nogni traccia su un file WAV separato (es. ..._voce.wav, ..._base.wav).\n\nIsolato di proposito: se qualcosa non va non tocca né la voce guida\nné il registratore WDM esistente.\n"""\n\nimport os\nimport time\nimport ctypes\nimport threading\nfrom collections import deque\n\ntry:\n    import numpy as np\n    import soundfile as sf\nexcept Exception:\n    np = None\n    sf = None\n\n# importa il modulo della voce guida per condividere device + libreria ASIO\ntry:\n    from . import cuffia_guida as _cg\nexcept Exception:\n    import cuffia_guida as _cg  # fallback se importato fuori dal package\n\n# Costanti BASSASIO\n# ⛔⛔ PARTONO DA 16, NON DA ZERO. E soprattutto: CHIEDERE UN FORMATO NON E\'\n#    OTTENERLO. Misurato sull\'XR18 il 13-09-2026:\n#        canale 0 -> formato 18   (INT32)\n#    cioe\' il driver X-AIR consegna interi a 32 bit e IGNORA la richiesta di\n#    float. Quei byte letti come float32 diventano numeri minuscoli\n#    (denormali), e nel registro del registratore si vedeva il risultato:\n#    18 file su 18 con `peak 0.00000`, cancellati tutti come "muti".\n#    Ecco perche\' "da diverso tempo non si riesce a registrare".\nBASS_ASIO_FORMAT_16BIT = 16\nBASS_ASIO_FORMAT_24BIT = 17\nBASS_ASIO_FORMAT_32BIT = 18\nBASS_ASIO_FORMAT_FLOAT = 19\nBYTE_FORMATO = {BASS_ASIO_FORMAT_16BIT: 2, BASS_ASIO_FORMAT_24BIT: 3,\n                BASS_ASIO_FORMAT_32BIT: 4, BASS_ASIO_FORMAT_FLOAT: 4}\nBASS_ASIO_RESET_ENABLE = 1\nBASS_ASIO_RESET_JOIN   = 2\n\n\ndef _in_float(pezzo: bytes, formato: int) -> np.ndarray:\n    """I byte grezzi diventano campioni da -1 a +1, secondo il formato VERO."""\n    if formato == BASS_ASIO_FORMAT_16BIT:\n        return np.frombuffer(pezzo, dtype="<i2").astype(np.float32) / 32768.0\n    if formato == BASS_ASIO_FORMAT_32BIT:\n        return np.frombuffer(pezzo, dtype="<i4").astype(np.float32) / 2147483648.0\n    if formato == BASS_ASIO_FORMAT_24BIT:\n        b = np.frombuffer(pezzo, dtype=np.uint8).reshape(-1, 3)\n        v = (b[:, 0].astype(np.int32)\n             | (b[:, 1].astype(np.int32) << 8)\n             | (b[:, 2].astype(np.int8).astype(np.int32) << 16))\n        return v.astype(np.float32) / 8388608.0\n    return np.frombuffer(pezzo, dtype=np.float32)\n\n# Firma del callback ASIO:\n#   DWORD CALLBACK ASIOPROC(BOOL input, DWORD channel, void *buffer, DWORD length, void *user)\nASIOPROC = ctypes.CFUNCTYPE(ctypes.c_ulong, ctypes.c_int, ctypes.c_ulong,\n                            ctypes.c_void_p, ctypes.c_ulong, ctypes.c_void_p)\n\n\n# Struct BASS_ASIO_INFO: serve solo il campo \'inputs\' (n. canali d\'ingresso del device)\nclass _BassAsioInfo(ctypes.Structure):\n    _fields_ = [\n        ("name",     ctypes.c_char_p),\n        ("version",  ctypes.c_ulong),\n        ("inputs",   ctypes.c_ulong),\n        ("outputs",  ctypes.c_ulong),\n        ("bufmin",   ctypes.c_ulong),\n        ("bufmax",   ctypes.c_ulong),\n        ("bufpref",  ctypes.c_ulong),\n        ("bufgran",  ctypes.c_long),\n        ("initflags", ctypes.c_ulong),\n    ]\n\n\n# Fallback se non si riesce a leggere il n. di canali dal device.\n# (gli indici sono i canali di INGRESSO ASIO, 0-based = USB send N-1)\nDEFAULT_TRACKS = [\n    ("voce", [0]),\n    ("base", [1, 2]),\n]\n\n\ndef _alog(_m):\n    """log flushato su rec_debug.log: sopravvive a un crash NATIVO di BASSASIO."""\n    try:\n        import os as _os\n        _p = _os.path.join(_os.path.dirname(__file__), \'..\', \'log\', \'rec_debug.log\')\n        with open(_p, \'a\', encoding=\'utf-8\') as _f:\n            _f.write("[rec-asio] " + _m + "\\n"); _f.flush()\n    except Exception:\n        pass\n    print("[rec-asio] " + _m, flush=True)\n\n\nclass RegistratoreASIO:\n    def __init__(self, tracks=None, samplerate=48000, subtype=\'PCM_24\'):\n        # tracks=None => modalità AUTOMATICA 1:1: registra TUTTI i canali\n        # d\'ingresso del device, uno per file (canale N -> ..._inN.wav).\n        self._auto = tracks is None\n        self.tracks = tracks or DEFAULT_TRACKS\n        self.samplerate = int(samplerate)\n        self.subtype = subtype\n        self.is_recording = False\n        self.levels = {}            # canale -> ultimo picco (0..1) per eventuali VU\n        self._chan = {}             # canale -> deque(bytes)\n        self.formati = {}           # canale -> formato VERO letto dal driver\n        self._files = []            # [{\'name\',\'chans\',\'file\',\'path\'}]\n        self._proc = None           # riferimento VIVO al callback (non rimuovere!)\n        self._writer = None\n        self._enabled = []          # canali realmente abilitati\n\n    # ---------- util ----------\n    def _all_channels(self):\n        chans = []\n        for _name, chlist in self.tracks:\n            chans.extend(chlist)\n        return chans\n\n    # NB: il vecchio probe (_get_input_count / _build_auto_tracks) e\' stato RIMOSSO:\n    # abilitava+resettava tutti i 18 canali prima della registrazione e mandava in\n    # stallo il driver mono-client dell\'XR18. Ora la scoperta dei canali avviene in\n    # start(), abilitando ciascun canale UNA sola volta (vedi commento in start()).\n\n    def available(self):\n        if np is None or sf is None:\n            return False\n        try:\n            return _cg._asio_lib.load()\n        except Exception:\n            return False\n\n    def _close_files(self):\n        for e in self._files:\n            try:\n                e[\'file\'].close()\n            except Exception:\n                pass\n        self._files = []\n\n    # ---------- avvio ----------\n    def start(self, output_folder, base_name):\n        if self.is_recording:\n            return False\n        if not self.available():\n            print("❌ Registrazione ASIO: BASSASIO / soundfile non disponibili")\n            return False\n\n        # device ASIO condiviso con la voce guida (lo inizializza se serve)\n        _alog("start: prima di _ensure_asio (init/hook ASIO XR18)")\n        try:\n            if not _cg.guida._ensure_asio():\n                print("❌ Registrazione ASIO: device XR18 ASIO non inizializzato")\n                return False\n        except Exception as e:\n            print(f"❌ Registrazione ASIO: _ensure_asio fallito: {e}")\n            return False\n        _alog("start: _ensure_asio OK")\n\n        a = _cg._asio_lib.asio\n\n        # firme dei metodi che usiamo (idempotente)\n        a.BASS_ASIO_ChannelEnable.restype = ctypes.c_bool\n        a.BASS_ASIO_ChannelEnable.argtypes = [ctypes.c_int, ctypes.c_ulong, ASIOPROC, ctypes.c_void_p]\n        a.BASS_ASIO_ChannelSetFormat.restype = ctypes.c_bool\n        a.BASS_ASIO_ChannelSetFormat.argtypes = [ctypes.c_int, ctypes.c_ulong, ctypes.c_ulong]\n        a.BASS_ASIO_ChannelGetFormat.restype = ctypes.c_int\n        a.BASS_ASIO_ChannelGetFormat.argtypes = [ctypes.c_int, ctypes.c_ulong]\n        try:\n            a.BASS_ASIO_ChannelSetRate.restype = ctypes.c_bool\n            a.BASS_ASIO_ChannelSetRate.argtypes = [ctypes.c_int, ctypes.c_ulong, ctypes.c_double]\n        except Exception:\n            pass\n\n        # IMPORTANTE: usa il sample rate REALE del device ASIO (di norma 48000),\n        # NON quello riportato dal lato WDM (es. 44100), altrimenti i file\n        # risultano a velocità/pitch sbagliati.\n        try:\n            a.BASS_ASIO_GetRate.restype = ctypes.c_double\n            real_rate = a.BASS_ASIO_GetRate()\n            if real_rate and real_rate > 0:\n                self.samplerate = int(round(real_rate))\n                print(f"[rec-asio] sample rate ASIO reale: {self.samplerate} Hz")\n        except Exception:\n            pass\n\n        # callback minimale: copia i byte nella coda del canale\n        self._chan = {}\n        self.levels = {}\n        self.formati = {}\n        def _cb(inp, channel, buffer, length, user):\n            try:\n                if self.is_recording and length:\n                    dq = self._chan.get(channel)\n                    if dq is not None:\n                        dq.append(ctypes.string_at(buffer, length))\n            except Exception:\n                pass\n            return length\n        self._proc = ASIOPROC(_cb)   # IMPORTANTISSIMO: tenerlo vivo\n\n        # per applicare i nuovi canali d\'ingresso, se il motore gira lo fermo un attimo;\n        # i canali della voce guida restano abilitati e riprendono al riavvio.\n        was_started = bool(a.BASS_ASIO_IsStarted())\n        if was_started:\n            a.BASS_ASIO_Stop()\n\n        # --- ABILITAZIONE canali: UNA SOLA volta per canale (NIENTE probe distruttivo).\n        #     Il vecchio codice PROVAVA tutti i canali (enable+reset) e POI li ri-abilitava:\n        #     quel doppio ciclo su 18 canali mandava in stallo il driver mono-client\n        #     dell\'XR18 e il callback non riceveva piu\' nulla (file da 44 byte).\n        #     auto  -> provo ch0,1,2... e mi fermo al PRIMO che il device rifiuta\n        #              (ChannelEnable su un canale inesistente ritorna False, niente crash);\n        #     lista -> solo i canali richiesti.\n        cand = list(range(64)) if self._auto else self._all_channels()\n        _alog(f"start: auto={self._auto} candidati={cand[:20]}{\'...\' if len(cand) > 20 else \'\'}")\n        self._enabled = []\n        for c in cand:\n            _alog(f"start: ChannelEnable input ch{c}")\n            try:\n                ok = bool(a.BASS_ASIO_ChannelEnable(True, c, self._proc, None))\n            except Exception as e:\n                _alog(f"start: enable ch{c} eccezione {e}")\n                ok = False\n            if not ok:\n                if self._auto:\n                    break   # fine dei canali d\'ingresso realmente presenti\n                print(f"[rec-asio] enable ingresso ch{c} err={a.BASS_ASIO_ErrorGetCode()}")\n                continue\n            # ⭐ si CHIEDE float, ma poi si RILEGGE cosa da\' davvero il driver:\n            #    l\'X-AIR risponde INT32 e ignora la richiesta (misurato).\n            a.BASS_ASIO_ChannelSetFormat(True, c, BASS_ASIO_FORMAT_FLOAT)\n            try:\n                vero = int(a.BASS_ASIO_ChannelGetFormat(True, c))\n            except Exception:\n                vero = -1\n            if vero not in BYTE_FORMATO:\n                _alog(f"start: ch{c} formato sconosciuto ({vero}): SALTATO")\n                try:\n                    a.BASS_ASIO_ChannelEnable(True, c, None, None)\n                except Exception:\n                    pass\n                continue\n            self.formati[c] = vero\n            if vero != BASS_ASIO_FORMAT_FLOAT:\n                _alog(f"start: ch{c} il driver da\' formato {vero}"\n                      f" ({BYTE_FORMATO[vero]} byte), converto io")\n            try:\n                a.BASS_ASIO_ChannelSetRate(True, c, float(self.samplerate))\n            except Exception:\n                pass\n            self._chan[c] = deque()\n            self.levels[c] = 0.0\n            self._enabled.append(c)\n\n        if not self._enabled:\n            print("❌ Registrazione ASIO: nessun canale d\'ingresso abilitato (controlla il routing USB sends)")\n            if was_started:\n                a.BASS_ASIO_Start(0, 0)\n            return False\n\n        # tracce definitive = solo i canali realmente abilitati (1:1, un file mono ciascuno)\n        if self._auto:\n            self.tracks = [("voce" if c == 0 else f"in{c + 1}", [c]) for c in self._enabled]\n        _alog(f"start: enabled={self._enabled} tracce={self.tracks}")\n\n        # apri i file traccia (solo per canali abilitati)\n        os.makedirs(output_folder, exist_ok=True)\n        self._files = []\n        try:\n            for name, chlist in self.tracks:\n                if not all(c in self._enabled for c in chlist):\n                    continue\n                fname = f"{base_name}_{name}.wav" if base_name else f"{name}.wav"\n                path = os.path.join(output_folder, fname)\n                f = sf.SoundFile(path, mode=\'w\', samplerate=self.samplerate,\n                                 channels=len(chlist), subtype=self.subtype)\n                self._files.append({\'name\': name, \'chans\': list(chlist), \'file\': f, \'path\': path})\n        except Exception as e:\n            print(f"❌ Registrazione ASIO: apertura file fallita: {e}")\n            self._close_files()\n            if was_started:\n                a.BASS_ASIO_Start(0, 0)\n            return False\n\n        self.is_recording = True\n        self._writer = threading.Thread(target=self._writer_loop, daemon=True)\n        self._writer.start()\n\n        if not a.BASS_ASIO_IsStarted():\n            _alog("start: BASS_ASIO_Start")\n            if not a.BASS_ASIO_Start(0, 0):\n                print(f"[rec-asio] ASIO_Start err={a.BASS_ASIO_ErrorGetCode()}")\n        _alog("start: AVVIATA OK")\n\n        print(f"⏺ Registrazione ASIO avviata: {[e[\'path\'] for e in self._files]}")\n        return True\n\n    # ---------- writer ----------\n    def _writer_loop(self):\n        while True:\n            progressed = False\n            for e in self._files:\n                chans = e[\'chans\']\n                if all(self._chan[c] for c in chans):\n                    chunks = [self._chan[c].popleft() for c in chans]\n                    # ⛔ NON si da\' per scontato il float: si converte dal\n                    #    formato VERO letto dal driver (vedi _in_float).\n                    arrs = [_in_float(ch, self.formati.get(c,\n                                                           BASS_ASIO_FORMAT_FLOAT))\n                            for ch, c in zip(chunks, chans)]\n                    n = min(arr.shape[0] for arr in arrs)\n                    if n <= 0:\n                        continue\n                    block = np.empty((n, len(chans)), dtype=np.float32)\n                    for i, arr in enumerate(arrs):\n                        seg = arr[:n]\n                        block[:, i] = seg\n                        if seg.size:\n                            self.levels[chans[i]] = float(np.abs(seg).max())\n                    try:\n                        e[\'file\'].write(block)\n                    except Exception as ex:\n                        print(f"[rec-asio] write {e[\'name\']}: {ex}")\n                    progressed = True\n            if not progressed:\n                if not self.is_recording and not any(self._chan[c] for c in self._all_channels()):\n                    break\n                time.sleep(0.004)\n\n    # ---------- stop ----------\n    def stop(self):\n        if not self.is_recording:\n            return []\n        self.is_recording = False\n        try:\n            a = _cg._asio_lib.asio\n            for c in self._enabled:\n                try:\n                    a.BASS_ASIO_ChannelReset(True, c,\n                                             BASS_ASIO_RESET_ENABLE | BASS_ASIO_RESET_JOIN)\n                except Exception:\n                    pass\n        except Exception:\n            pass\n        # lascio il motore ASIO acceso: la voce guida può ancora servirsene\n        if self._writer:\n            try:\n                self._writer.join(timeout=3.0)\n            except Exception:\n                pass\n        paths = [e[\'path\'] for e in self._files]\n        self._close_files()\n        self._proc = None\n        self._enabled = []\n        # In modalità AUTO (tutti i canali) cancella i file MUTI: gli USB-send non\n        # collegati dell\'XR18 producono un file di puro silenzio -> spazzatura. Cosi\'\n        # restano solo le tracce con segnale reale (mic + eventuali strumenti).\n        # In modalità a canali SCELTI non si cancella nulla: l\'utente li ha chiesti.\n        if self._auto:\n            paths = self._cleanup_silent_files(paths)\n        # ✅ Normalizzazione automatica anche in multitraccia (stesso criterio del\n        #    percorso standard): i file vengono scritti in streaming, quindi la\n        #    passata avviene DOPO la chiusura, rileggendo e riscrivendo ogni traccia.\n        self._normalize_files(paths)\n        print(f"⏹ Registrazione ASIO salvata: {paths}")\n        return paths\n\n    def _cleanup_silent_files(self, paths):\n        """Cancella i WAV muti (canale non collegato) e ritorna solo quelli con segnale.\n        Muto = 0 frame (file da ~44 byte) oppure picco sotto ~-62 dBFS su tutta la\n        durata. Se TUTTI risultassero muti (ASIO non ha ricevuto nulla) li cancella\n        comunque: 0 file e\' meglio di una cartella di file inutili."""\n        if np is None or sf is None:\n            return paths\n        SILENT_PEAK = 0.0008   # ~ -62 dBFS: sotto = canale non collegato\n        vivi = []\n        for p in paths:\n            try:\n                data, _sr = sf.read(p, always_2d=True)\n                peak = float(np.abs(data).max()) if data.size else 0.0\n            except Exception as ex:\n                _alog(f"cleanup: lettura {os.path.basename(p)} fallita ({ex}) -> tengo il file")\n                vivi.append(p)\n                continue\n            if peak < SILENT_PEAK:\n                try:\n                    os.remove(p)\n                    _alog(f"cleanup: rimosso muto {os.path.basename(p)} (peak {peak:.5f})")\n                except Exception as ex:\n                    _alog(f"cleanup: impossibile rimuovere {os.path.basename(p)}: {ex}")\n                    vivi.append(p)\n            else:\n                vivi.append(p)\n        return vivi\n\n    # target di LOUDNESS della voce quando canta (RMS dei frame attivi). La peak-\n    # normalize non basta: se un solo transiente (respiro/pop/colpo) tocca lo 0 dB,\n    # il picco e\' "gia\' pieno" e il corpo della voce resta a -30 dB -> suona basso.\n    TARGET_RMS_DB = -18.0     # RMS del cantato; ~ -16 LUFS, voce piena ma non schiacciata\n    MAX_GAIN_DB = 24.0        # tetto: oltre = input troppo basso alla fonte\n    CEILING = 0.94            # ~ -0.5 dBFS, il limiter contiene i transienti\n\n    @staticmethod\n    def _active_rms(mono):\n        """RMS del CANTATO: media sui frame non-silenzio (sopra -50 dBFS assoluti), cosi\'\n        i silenzi tra le frasi non abbassano la misura e il livello riflette la voce\n        reale (forte E piano insieme), non solo i picchi."""\n        fr = 4096\n        n = len(mono) // fr\n        if n < 1:\n            return float(np.sqrt(np.mean(mono ** 2)) + 1e-12)\n        segs = mono[:n * fr].reshape(n, fr)\n        e = np.sqrt((segs ** 2).mean(1))\n        act = e[e > 10.0 ** (-50.0 / 20.0)]      # frame non-silenzio (soglia assoluta)\n        if act.size < max(1, int(n * 0.05)):     # quasi tutto silenzio -> RMS globale\n            return float(np.sqrt(np.mean(mono ** 2)) + 1e-12)\n        return float(np.sqrt(np.mean(act ** 2)) + 1e-12)\n\n    @classmethod\n    def _soft_limit(cls, y):\n        """Limiter morbido: sopra il ginocchio comprime con tanh (trasparente sui\n        transienti brevi), niente clip duro."""\n        knee = cls.CEILING * 0.85\n        a = np.abs(y)\n        over = a > knee\n        if np.any(over):\n            comp = knee + (cls.CEILING - knee) * np.tanh((a - knee) / max(cls.CEILING - knee, 1e-6))\n            y = np.where(over, np.sign(y) * comp, y)\n        return y.astype(np.float32)\n\n    def _normalize_files(self, paths):\n        """Porta ogni traccia a una LOUDNESS coerente (RMS del cantato ~ TARGET_RMS_DB)\n        + limiter morbido sui picchi. Se la normalizzazione e\' spenta (config\n        rec_normalize=false) applica invece il guadagno manuale dello slider\n        \'Vol microfono\' (rec_mic_vol), che nel percorso ASIO prima veniva IGNORATO.\n        Preserva il subtype (es. PCM_24)."""\n        try:\n            from .database import Database\n        except Exception:\n            try:\n                from database import Database\n            except Exception:\n                Database = None\n        normalize_on = True\n        mic_vol = 1.0\n        if Database is not None:\n            try:\n                normalize_on = (Database.get_config(\'rec_normalize\', \'true\') == \'true\')\n            except Exception:\n                pass\n            try:\n                mic_vol = max(0.0, float(Database.get_config(\'rec_mic_vol\', \'100\')) / 100.0)\n            except Exception:\n                mic_vol = 1.0\n        for p in paths:\n            try:\n                data, sr = sf.read(p, always_2d=True)\n                if not data.size:\n                    continue\n                mono = data.mean(1)\n                if normalize_on:\n                    rms = self._active_rms(mono)\n                    gain = 10.0 ** ((self.TARGET_RMS_DB - 20.0 * np.log10(rms + 1e-12)) / 20.0)\n                    gain = float(min(gain, 10.0 ** (self.MAX_GAIN_DB / 20.0)))\n                    modo = "loudness"\n                else:\n                    gain = mic_vol            # guadagno manuale dello slider\n                    modo = "manuale slider"\n                if gain <= 0.0 or abs(gain - 1.0) < 0.02:\n                    continue\n                y = self._soft_limit(data * gain)\n                try:\n                    sub = sf.info(p).subtype\n                except Exception:\n                    sub = self.subtype\n                sf.write(p, y, sr, subtype=sub)\n                gdb = 20.0 * np.log10(gain)\n                _alog(f"normalize {os.path.basename(p)} [{modo}]: +{gdb:.1f} dB")\n                if normalize_on and gdb >= 18.0:\n                    _alog(f"⚠️ {os.path.basename(p)}: applicati +{gdb:.1f} dB -> il segnale "\n                          f"entra MOLTO basso: alza il GAIN del canale sull\'XR18 (o il tap USB).")\n            except Exception as ex:\n                _alog(f"normalize {os.path.basename(p)} err: {ex}")\n'

CODICE_GEMELLO = 'def _gemello_wasapi(indice):\n        """Lo STESSO dispositivo, ma sotto WASAPI invece che MME.\n\n        ⛔⛔ MISURATO sull\'XR18 il 13-09-2026. Lo stesso ingresso compare\n        sotto quattro driver, e non dicono la stessa cosa:\n\n            1  IN 1-2 (BEHRINGER X-AIR)  MME       -> dichiara 44100 Hz\n           19  IN 1-2 (BEHRINGER X-AIR)  DirectSound -> 44100 Hz\n           45  IN 1-2 (BEHRINGER X-AIR)  WASAPI    -> 48000 Hz  (il vero)\n           61  IN 1-2 (IN 1-2)           WDM-KS    -> 48000 Hz\n\n        Il mixer gira a 48000. Aprendo il device MME (che dichiara 44100)\n        PortAudio si pianta DENTRO l\'apertura, nativamente: in\n        `rec_debug.log` il log si interrompe di netto dopo la riga\n        "-> WDM sd.InputStream device=1 ... sr=44100", tre volte di fila, e\n        non arriva ne\' un errore ne\' un\'eccezione. Provato qui: il gemello\n        WASAPI si apre e consegna campioni, quello MME no.\n\n        ⚠️ Non si puo\' scegliere in base al sample rate "dichiarato": MME\n        accetta qualunque frequenza (ricampiona) e `check_input_settings`\n        risponde di si\' anche quando poi l\'apertura si pianta.\n        """\n        try:\n            import sounddevice as _sd\n            d = _sd.query_devices(indice)\n            api = _sd.query_hostapis(d[\'hostapi\'])[\'name\']\n            if \'MME\' not in api and \'DirectSound\' not in api:\n                return indice          # gia\' WASAPI/WDM-KS: va bene cosi\'\n            nome = (d[\'name\'] or \'\').strip()\n            candidati = []\n            for i, altro in enumerate(_sd.query_devices()):\n                if i == indice or altro[\'max_input_channels\'] <= 0:\n                    continue\n                if (altro[\'name\'] or \'\').strip() != nome:\n                    continue\n                a = _sd.query_hostapis(altro[\'hostapi\'])[\'name\']\n                if \'WASAPI\' in a:\n                    candidati.append((0, i, a))\n                elif \'WDM-KS\' in a:\n                    candidati.append((1, i, a))\n            if not candidati:\n                return indice\n            candidati.sort()\n            _peso, i, a = candidati[0]\n            return i\n        except Exception:\n            return indice'


def apply():
    try:
        m = sys.modules.get('moduli.registratore_asio')
        if m is not None and hasattr(m, '_in_float') \
                and not getattr(m, '_s049', False):
            traccia('il programma lo fa gia da se')
            return True
        import types
        import moduli
        if m is None:
            m = types.ModuleType('moduli.registratore_asio')
        m.__package__ = 'moduli'
        if not getattr(m, '__file__', None):
            import os
            try:
                dove = os.path.dirname(moduli.__file__)
            except Exception:
                dove = os.path.dirname(os.path.abspath(sys.argv[0]))
            m.__file__ = os.path.join(dove, 'registratore_asio.py')
        exec(compile(CODICE, '<patch049>', 'exec'), m.__dict__)
        m._s049 = True
        sys.modules['moduli.registratore_asio'] = m
        setattr(moduli, 'registratore_asio', m)
        traccia('il registratore legge il formato VERO del driver')
        _il_gemello()
        return True
    except Exception as e:
        traccia('non agganciata: %s: %s' % (type(e).__name__, e))
        return False


def _il_gemello():
    try:
        r = sys.modules.get('moduli.registratore')
        if r is None:
            import moduli.registratore as r
        cls = getattr(r, 'Registratore', None)
        if cls is None:
            traccia('classe Registratore non trovata')
            return False
        if getattr(cls, '_gemello_wasapi', None) is not None                 and not getattr(cls, '_s049', False):
            traccia('il gemello lo fa gia da se')
            return True
        sp = {}
        exec(compile(CODICE_GEMELLO, '<patch049_gem>', 'exec'), r.__dict__, sp)
        gem = sp.get('_gemello_wasapi')
        if gem is None:
            return False
        cls._gemello_wasapi = staticmethod(gem)
        cls._s049 = True
        vera = cls._start_recording

        def _start_recording(self, _v=vera):
            try:
                for campo in ('selected_device', 'selected_mic'):
                    i = getattr(self, campo, None)
                    if i is None:
                        continue
                    g = cls._gemello_wasapi(i)
                    if g != i:
                        setattr(self, campo, g)
                        traccia('%s: %s -> %s (dal driver giusto)'
                                % (campo, i, g))
                if getattr(self, 'selected_mic', None) is not None and                         self.selected_mic == getattr(self, 'selected_device', None):
                    traccia('microfono e sorgente sono lo stesso ingresso:'
                            ' un flusso solo')
                    self.selected_mic = None
            except Exception as e:
                traccia('scelta del driver non corretta: %s' % e)
            return _v(self)

        _start_recording._s049 = True
        cls._start_recording = _start_recording
        traccia('registratore: via da MME, si usa il gemello WASAPI')
        return True
    except Exception as e:
        traccia('gemello non agganciato: %s: %s' % (type(e).__name__, e))
        return False


def revert():
    return False


try:
    apply()
except Exception:
    pass
